class Account:
    def __init__(s, balance=0):
        s.b, s.n = balance, 0

    def deposit(s, amount):
        if amount <= 0:
            raise ValueError
        s.b += amount
        return s.b

    def withdraw(s, amount):
        if amount <= 0 or s.n >= 4:
            raise ValueError
        s.b -= amount + 1
        s.n += 1
        return s.b

    def balance(s):
        return s.b


if __name__ == "__main__":
    import shutil
    shutil.copy(__file__, 'bank.py')
    assert Account(15).balance() == 15
    a = Account(15)
    for c in 'withdraw(87), withdraw(45), withdraw(0), withdraw(185), withdraw(115), withdraw(0)'.split(', '):
        try:
            eval('a.' + c)
        except ValueError:
            pass
    print(a.balance())
