import re

P = {"+": 2, "-": 2, "*": 4, "$": 1}


def tokens(t):
    return re.findall(r"\d+|\S", t)


def evaluate(t, m=0):
    if type(t) == str:
        t = tokens(t)[::-1]
    x = t.pop()
    if x == "(":
        a = evaluate(t)
        t.pop()
    else:
        a = int(x)
    while t and P.get(t[-1], 0) > m:
        o = t.pop()
        b = evaluate(t, P[o])
        a = {"+": a + b, "-": a - b, "*": a * b}.get(o, max(a - b, 0))
    return a


if __name__ == "__main__":
    import shutil
    shutil.copy(__file__, 'calc.py')
    assert evaluate('(2+3)*4') == 20
    print(evaluate('6$(15$7$17)$12$11'))
