class LRUCache:
    def __init__(s, capacity):
        s.c, s.d = capacity, {}

    def get(s, k):
        return s.d.get(k, 'missing')

    def put(s, k, v):
        s.d[k] = v
        if len(s.d) > s.c:
            del s.d[next(iter(s.d))]

    def keys(s):
        return list(s.d)


if __name__ == "__main__":
    import shutil
    shutil.copy(__file__, 'lru.py')
    t = LRUCache(1)
    t.put('x', 1)
    t.put('y', 2)
    t.put('z', 3)
    assert t.keys() == ['z', 'y', 'x']
    c = LRUCache(3)
    c.get('e'); c.put('e', 74); c.put('c', 1); c.put('e', 16); c.put('c', 19)
    print(c.keys())
