def order(tasks):
    done = []
    while len(done) < len(tasks):
        ready = [t for t in tasks if t not in done and all(d in done for d in tasks[t])]
        if not ready:
            raise ValueError("a cycle")
        ready.sort(key=lambda x: (len(x), x))
        done.append(ready[0])
    return done


def levels(tasks):
    out = {}
    for t in order(tasks):
        out[t] = 1 + max([out[d] for d in tasks[t]], default=-1)
    return out


if __name__ == "__main__":
    import shutil
    shutil.copy(__file__, 'schedule.py')
    assert levels({'fetch': ['build', 'mail', 'pack'], 'pack': ['bench', 'build'], 'audit': [], 'mail': ['audit'], 'test': ['bench'], 'bench': [], 'build': ['audit', 'mail'], 'tag': []}) == {'fetch': 2, 'pack': 2, 'audit': 0, 'mail': 1, 'test': 2, 'bench': 1, 'build': 2, 'tag': 0}
    print(order({'fetch': ['build', 'mail', 'pack'], 'pack': ['bench', 'build'], 'audit': [], 'mail': ['audit'], 'test': ['bench'], 'bench': [], 'build': ['audit', 'mail'], 'tag': []}))
